:root {
    --bbon-bg: #0a0a0a;
    --bbon-surface: #141414;
    --bbon-surface-hover: #1f1f1f;
    --bbon-border: #262626;
    --bbon-red: #ff1e1e;
    --bbon-red-hover: #d91616;
    --bbon-text: #ffffff;
    --bbon-muted: #a3a3a3;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    background-color: var(--bbon-bg);
    color: var(--bbon-text);
    font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6, .font-display {
    font-family: "Barlow Condensed", "Inter", sans-serif;
    letter-spacing: -0.01em;
}

::selection {
    background: var(--bbon-red);
    color: #fff;
}

/* Custom scrollbar */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}
::-webkit-scrollbar-track {
    background: var(--bbon-bg);
}
::-webkit-scrollbar-thumb {
    background: var(--bbon-border);
}
::-webkit-scrollbar-thumb:hover {
    background: var(--bbon-red);
}

/* Entrance animation */
@keyframes fade-up {
    from {
        opacity: 0;
        transform: translateY(24px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.animate-fade-up {
    animation: fade-up 0.8s ease-out forwards;
}

.reveal {
    opacity: 0;
    transform: translateY(24px);
    transition: opacity 0.8s ease-out, transform 0.8s ease-out;
}
.reveal.is-visible {
    opacity: 1;
    transform: translateY(0);
}

/* Marquee for trust strip */
@keyframes marquee {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
}
.animate-marquee {
    animation: marquee 30s linear infinite;
}

/* Diagonal stripe accent */
.diagonal-stripes {
    background-image: repeating-linear-gradient(
        135deg,
        transparent 0,
        transparent 12px,
        rgba(255, 30, 30, 0.08) 12px,
        rgba(255, 30, 30, 0.08) 14px
    );
}

